const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

// UI Elements
const scoreEl = document.getElementById('score');
const highScoreEl = document.getElementById('high-score');
const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');
const finalScoreEl = document.getElementById('final-score');
const finalShardsEl = document.getElementById('final-shards');

// Game States
const STATE_START = 'START';
const STATE_PLAYING = 'PLAYING';
const STATE_GAMEOVER = 'GAMEOVER';
let gameState = STATE_START;

// Game variables
let score = 0;
let highScore = localStorage.getItem('cyberRunnerHighScore') || 0;
let shardsCollected = 0;
let gameSpeed = 6;
let spawnTimer = 0;
let spawnInterval = 90; // frames
let frameCount = 0;

highScoreEl.textContent = highScore;

// Player object
const player = {
    x: 80,
    y: 300,
    width: 40,
    height: 50,
    vy: 0,
    jumpForce: -12,
    gravity: 0.6,
    isJumping: false,
    isDuck: false,
    normalHeight: 50,
    duckHeight: 25,
    color: '#00f0ff',
    trail: []
};

// Arrays for obstacles and collectibles
let obstacles = [];
let collectibles = [];
let particles = [];
let gridLines = [];

// Initialize background grid lines
for (let i = 0; i < 20; i++) {
    gridLines.push({
        x: i * 50,
        speed: 2
    });
}

// Input handling
const keys = {};

window.addEventListener('keydown', e => {
    if (['Space', 'ArrowUp', 'ArrowDown', ' '].includes(e.key)) {
        e.preventDefault(); // prevent scrolling
    }
    keys[e.key] = true;

    if (gameState === STATE_PLAYING) {
        if ((e.key === ' ' || e.key === 'ArrowUp') && !player.isJumping) {
            player.vy = player.jumpForce;
            player.isJumping = true;
            player.isDuck = false;
            player.height = player.normalHeight;
            createJumpParticles();
        }
    }
});

window.addEventListener('keyup', e => {
    keys[e.key] = false;
});

canvas.addEventListener('click', () => {
    if (gameState === STATE_START) {
        startGame();
    } else if (gameState === STATE_PLAYING && !player.isJumping) {
        player.vy = player.jumpForce;
        player.isJumping = true;
        player.isDuck = false;
        player.height = player.normalHeight;
        createJumpParticles();
    }
});

startBtn.addEventListener('click', startGame);
restartBtn.addEventListener('click', startGame);

function startGame() {
    gameState = STATE_PLAYING;
    score = 0;
    shardsCollected = 0;
    gameSpeed = 6;
    spawnTimer = 0;
    spawnInterval = 90;
    frameCount = 0;
    obstacles = [];
    collectibles = [];
    particles = [];

    player.y = 300;
    player.vy = 0;
    player.isJumping = false;
    player.isDuck = false;
    player.height = player.normalHeight;

    scoreEl.textContent = '0';
    startScreen.classList.add('hidden');
    gameOverScreen.classList.add('hidden');
}

function gameOver() {
    gameState = STATE_GAMEOVER;
    if (score > highScore) {
        highScore = Math.floor(score);
        localStorage.setItem('cyberRunnerHighScore', highScore);
        highScoreEl.textContent = highScore;
    }
    finalScoreEl.textContent = Math.floor(score);
    finalShardsEl.textContent = shardsCollected;
    gameOverScreen.classList.remove('hidden');
    createExplosionParticles(player.x + player.width/2, player.y + player.height/2);
}

// Particle Effects
function createJumpParticles() {
    for (let i = 0; i < 8; i++) {
        particles.push({
            x: player.x + player.width / 2,
            y: player.y + player.height,
            vx: (Math.random() - 0.5) * 4,
            vy: Math.random() * 2,
            size: Math.random() * 3 + 1,
            color: '#00f0ff',
            alpha: 1,
            decay: 0.03
        });
    }
}

function createExplosionParticles(x, y) {
    for (let i = 0; i < 30; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 6 + 2;
        particles.push({
            x: x,
            y: y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            size: Math.random() * 4 + 2,
            color: Math.random() > 0.5 ? '#ff007f' : '#00f0ff',
            alpha: 1,
            decay: 0.02
        });
    }
}

function createShardParticles(x, y) {
    for (let i = 0; i < 10; i++) {
        const angle = Math.random() * Math.PI * 2;
        const speed = Math.random() * 4 + 1;
        particles.push({
            x: x,
            y: y,
            vx: Math.cos(angle) * speed,
            vy: Math.sin(angle) * speed,
            size: Math.random() * 3 + 1,
            color: '#00f0ff',
            alpha: 1,
            decay: 0.04
        });
    }
}

// Game Loop Updates
function update() {
    if (gameState !== STATE_PLAYING) return;

    frameCount++;
    score += 0.1;
    scoreEl.textContent = Math.floor(score);

    // Increase difficulty gradually
    gameSpeed = 6 + Math.floor(score / 100) * 0.5;
    spawnInterval = Math.max(45, 90 - Math.floor(score / 50) * 5);

    // Player duck handling
    if (keys['ArrowDown'] || keys['s'] || keys['S']) {
        if (!player.isJumping) {
            player.isDuck = true;
            player.height = player.duckHeight;
            // Adjust y so player stays on ground while ducking
            player.y = 350 - player.height;
        }
    } else {
        if (player.isDuck && !player.isJumping) {
            player.isDuck = false;
            player.height = player.normalHeight;
            player.y = 350 - player.height;
        }
    }

    // Player physics
    player.vy += player.gravity;
    player.y += player.vy;

    // Ground collision
    const groundY = 350 - player.height;
    if (player.y >= groundY) {
        player.y = groundY;
        player.vy = 0;
        player.isJumping = false;
        if (player.isDuck) {
            player.height = player.duckHeight;
            player.y = 350 - player.height;
        }
    }

    // Player trail
    if (frameCount % 3 === 0) {
        player.trail.push({ x: player.x, y: player.y, height: player.height });
        if (player.trail.length > 5) player.trail.shift();
    }

    // Spawn obstacles and collectibles
    spawnTimer++;
    if (spawnTimer >= spawnInterval) {
        spawnTimer = 0;
        const rand = Math.random();

        if (rand < 0.6) {
            // Ground obstacle (barrier)
            obstacles.push({
                x: canvas.width,
                y: 300,
                width: 30,
                height: 50,
                type: 'ground',
                color: '#ff007f'
            });
        } else if (rand < 0.85) {
            // Flying drone obstacle (requires ducking or precise jump)
            obstacles.push({
                x: canvas.width,
                y: 230,
                width: 40,
                height: 25,
                type: 'air',
                color: '#ffe600'
            });
        } else {
            // Collectible shard cluster
            collectibles.push({
                x: canvas.width,
                y: Math.random() > 0.5 ? 260 : 200,
                width: 20,
                height: 20,
                collected: false
            });
        }
    }

    // Update obstacles
    for (let i = obstacles.length - 1; i >= 0; i--) {
        obstacles[i].x -= gameSpeed;

        // Collision detection (AABB)
        if (
            player.x < obstacles[i].x + obstacles[i].width &&
            player.x + player.width > obstacles[i].x &&
            player.y < obstacles[i].y + obstacles[i].height &&
            player.y + player.height > obstacles[i].y
        ) {
            gameOver();
        }

        // Remove offscreen obstacles
        if (obstacles[i].x + obstacles[i].width < 0) {
            obstacles.splice(i, 1);
        }
    }

    // Update collectibles
    for (let i = collectibles.length - 1; i >= 0; i--) {
        collectibles[i].x -= gameSpeed;

        // Collision detection for collectibles
        if (
            !collectibles[i].collected &&
            player.x < collectibles[i].x + collectibles[i].width &&
            player.x + player.width > collectibles[i].x &&
            player.y < collectibles[i].y + collectibles[i].height &&
            player.y + player.height > collectibles[i].y
        ) {
            collectibles[i].collected = true;
            shardsCollected++;
            score += 25;
            createShardParticles(collectibles[i].x + 10, collectibles[i].y + 10);
        }

        if (collectibles[i].x + collectibles[i].width < 0 || collectibles[i].collected) {
            collectibles.splice(i, 1);
        }
    }

    // Update particles
    for (let i = particles.length - 1; i >= 0; i--) {
        let p = particles[i];
        p.x += p.vx;
        p.y += p.vy;
        p.alpha -= p.decay;
        if (p.alpha <= 0) {
            particles.splice(i, 1);
        }
    }

    // Update grid lines
    gridLines.forEach(line => {
        line.x -= gameSpeed * 0.5;
        if (line.x < 0) line.x = canvas.width;
    });
}

// Rendering
function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw Cyberpunk Background Grid / Horizon
    ctx.strokeStyle = 'rgba(0, 240, 255, 0.08)';
    ctx.lineWidth = 1;
    gridLines.forEach(line => {
        ctx.beginPath();
        ctx.moveTo(line.x, 0);
        ctx.lineTo(line.x, 350);
        ctx.stroke();
    });

    // Horizontal grid lines
    for (let y = 0; y <= 350; y += 50) {
        ctx.beginPath();
        ctx.moveTo(0, y);
        ctx.lineTo(canvas.width, y);
        ctx.stroke();
    }

    // Draw glowing horizon line
    ctx.strokeStyle = '#ff007f';
    ctx.shadowColor = '#ff007f';
    ctx.shadowBlur = 10;
    ctx.lineWidth = 2;
    ctx.beginPath();
    ctx.moveTo(0, 350);
    ctx.lineTo(canvas.width, 350);
    ctx.stroke();
    ctx.shadowBlur = 0; // reset

    // Draw background city skyline silhouettes
    ctx.fillStyle = '#0a0f1d';
    ctx.fillRect(100, 200, 60, 150);
    ctx.fillRect(180, 150, 80, 200);
    ctx.fillRect(350, 180, 90, 170);
    ctx.fillRect(520, 130, 70, 220);
    ctx.fillRect(650, 170, 100, 180);

    // Draw player trail
    player.trail.forEach((t, idx) => {
        let alpha = (idx + 1) / player.trail.length * 0.3;
        ctx.fillStyle = `rgba(0, 240, 255, ${alpha})`;
        ctx.fillRect(t.x, t.y, player.width, t.height);
    });

    // Draw player
    ctx.shadowColor = player.color;
    ctx.shadowBlur = 12;
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Player inner visor detail
    ctx.fillStyle = '#ff007f';
    if (!player.isDuck) {
        ctx.fillRect(player.x + 20, player.y + 10, 15, 6);
    } else {
        ctx.fillRect(player.x + 20, player.y + 6, 15, 4);
    }
    ctx.shadowBlur = 0;

    // Draw obstacles
    obstacles.forEach(obs => {
        ctx.shadowColor = obs.color;
        ctx.shadowBlur = 10;
        ctx.fillStyle = obs.color;
        ctx.fillRect(obs.x, obs.y, obs.width, obs.height);

        // Inner core detail
        ctx.fillStyle = '#05070d';
        ctx.fillRect(obs.x + 6, obs.y + 6, obs.width - 12, obs.height - 12);
        ctx.shadowBlur = 0;
    });

    // Draw collectibles (Data Shards - rotating diamond appearance)
    collectibles.forEach(col => {
        ctx.shadowColor = '#00f0ff';
        ctx.shadowBlur = 15;
        ctx.fillStyle = '#00f0ff';

        ctx.save();
        ctx.translate(col.x + col.width / 2, col.y + col.height / 2);
        ctx.rotate((frameCount * 0.05) % (Math.PI * 2));
        ctx.fillRect(-col.width/3, -col.height/3, (col.width/3)*2, (col.height/3)*2);
        ctx.restore();
        ctx.shadowBlur = 0;
    });

    // Draw particles
    particles.forEach(p => {
        ctx.save();
        ctx.globalAlpha = p.alpha;
        ctx.shadowColor = p.color;
        ctx.shadowBlur = 8;
        ctx.fillStyle = p.color;
        ctx.fillRect(p.x, p.y, p.size, p.size);
        ctx.restore();
    });
}

// Main Game Loop
function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

// Start loop
requestAnimationFrame(gameLoop);

