// Neon Runner Game with Double Jump & Polish
const canvas = document.getElementById('gameCanvas');
const ctx = canvas.getContext('2d');

const startScreen = document.getElementById('start-screen');
const gameOverScreen = document.getElementById('game-over-screen');
const startBtn = document.getElementById('start-btn');
const restartBtn = document.getElementById('restart-btn');
const scoreValEl = document.getElementById('score-val');
const highscoreValEl = document.getElementById('highscore-val');
const finalScoreEl = document.getElementById('final-score');

// Game states
let gameState = 'START'; // START, PLAYING, GAMEOVER
let score = 0;
let highScore = localStorage.getItem('neon_runner_highscore') || 0;
highscoreValEl.textContent = highScore;

let gameSpeed = 5;
let gravity = 0.6;

// Player object
const player = {
  x: 80,
  y: 260,
  width: 40,
  height: 50,
  vy: 0,
  jumpForce: -11,
  jumpsRemaining: 2,
  maxJumps: 2,
  isGrounded: false,
  color: '#00f3ff',
  glowColor: 'rgba(0, 243, 255, 0.6)',
  particles: []
};

// Obstacles array
let obstacles = [];
let obstacleTimer = 0;
let obstacleInterval = 90; // frames

// Background stars/particles for parallax effect
let bgParticles = [];
for (let i = 0; i < 50; i++) {
  bgParticles.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    size: Math.random() * 2 + 1,
    speed: Math.random() * 1.5 + 0.5
  });
}

function resetGame() {
  score = 0;
  scoreValEl.textContent = '0';
  gameSpeed = 6;
  obstacles = [];
  obstacleTimer = 0;
  player.y = 260;
  player.vy = 0;
  player.jumpsRemaining = 2;
  player.particles = [];
  gameState = 'PLAYING';
  startScreen.classList.add('hidden');
  gameOverScreen.classList.add('hidden');
}

function triggerJump() {
  if (gameState !== 'PLAYING') return;

  if (player.jumpsRemaining > 0) {
    player.vy = player.jumpForce;
    player.jumpsRemaining--;
    player.isGrounded = false;

    // Spawn jump particles
    for (let i = 0; i < 12; i++) {
      player.particles.push({
        x: player.x + player.width / 2,
        y: player.y + player.height,
        vx: (Math.random() - 0.5) * 6,
        vy: Math.random() * 4 + 1,
        size: Math.random() * 4 + 2,
        alpha: 1,
        color: player.jumpsRemaining === 0 ? '#ff007f' : '#00f3ff'
      });
    }
  }
}

// Input listeners
window.addEventListener('keydown', (e) => {
  if (e.code === 'Space' || e.code === 'ArrowUp') {
    e.preventDefault();
    if (gameState === 'START') {
      resetGame();
    } else if (gameState === 'PLAYING') {
      triggerJump();
    } else if (gameState === 'GAMEOVER') {
      resetGame();
    }
  }
});

canvas.addEventListener('click', () => {
  if (gameState === 'START') {
    resetGame();
  } else if (gameState === 'PLAYING') {
    triggerJump();
  } else if (gameState === 'GAMEOVER') {
    resetGame();
  }
});

startBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  resetGame();
});

restartBtn.addEventListener('click', (e) => {
  e.stopPropagation();
  resetGame();
});

function spawnObstacle() {
  const types = ['spike', 'tall', 'floating'];
  const type = types[Math.floor(Math.random() * types.length)];

  let obs = {
    x: canvas.width,
    width: 30,
    height: 40,
    y: 270,
    color: '#ff007f',
    type: type
  };

  if (type === 'spike') {
    obs.width = 30;
    obs.height = 45;
    obs.y = 265;
  } else if (type === 'tall') {
    obs.width = 35;
    obs.height = 70;
    obs.y = 240;
    obs.color = '#bd00ff';
  } else if (type === 'floating') {
    obs.width = 40;
    obs.height = 30;
    obs.y = 180; // hovering obstacle
    obs.color = '#ffff00';
  }

  obstacles.push(obs);
}

function update() {
  if (gameState !== 'PLAYING') return;

  // Score increment & difficulty scaling
  score += 0.1;
  scoreValEl.textContent = Math.floor(score);
  if (Math.floor(score) % 300 === 0 && Math.floor(score) > 0) {
    gameSpeed = 6 + Math.floor(score / 300) * 0.8;
  }

  // Background particles update
  bgParticles.forEach(p => {
    p.x -= p.speed;
    if (p.x < 0) p.x = canvas.width;
  });

  // Player physics
  player.vy += gravity;
  player.y += player.vy;

  // Ground collision (floor is at y = 310, height of player is 50 -> ground y = 310 - 50 = 260)
  const groundLevel = 310 - player.height;
  if (player.y >= groundLevel) {
    player.y = groundLevel;
    player.vy = 0;
    player.isGrounded = true;
    player.jumpsRemaining = player.maxJumps;
  }

  // Update player particles
  player.particles.forEach((p, index) => {
    p.x += p.vx;
    p.y += p.vy;
    p.alpha -= 0.04;
    if (p.alpha <= 0) {
      player.particles.splice(index, 1);
    }
  });

  // Obstacle spawning
  obstacleTimer++;
  if (obstacleTimer >= obstacleInterval) {
    spawnObstacle();
    obstacleTimer = 0;
    // Vary interval slightly for dynamic challenge
    obstacleInterval = Math.floor(Math.random() * 50) + 70 - Math.min(gameSpeed * 2, 30);
  }

  // Update obstacles
  for (let i = obstacles.length - 1; i >= 0; i--) {
    let obs = obstacles[i];
    obs.x -= gameSpeed;

    // Remove off-screen obstacles
    if (obs.x + obs.width < 0) {
      obstacles.splice(i, 1);
      continue;
    }

    // AABB Collision Detection (with slight hitbox padding for fairness)
    const padding = 6;
    if (
      player.x + padding < obs.x + obs.width - padding &&
      player.x + player.width - padding > obs.x + padding &&
      player.y + padding < obs.y + obs.height - padding &&
      player.y + player.height - padding > obs.y + padding
    ) {
      // Collision!
      gameState = 'GAMEOVER';
      finalScoreEl.textContent = Math.floor(score);
      if (Math.floor(score) > highScore) {
        highScore = Math.floor(score);
        localStorage.setItem('neon_runner_highscore', highScore);
        highscoreValEl.textContent = highScore;
      }
      gameOverScreen.classList.remove('hidden');
    }
  }
}

function draw() {
  // Clear canvas with crisp background
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw background glowing grid / horizon
  ctx.strokeStyle = 'rgba(0, 243, 255, 0.07)';
  ctx.lineWidth = 1;
  for (let x = 0; x < canvas.width; x += 40) {
    ctx.beginPath();
    ctx.moveTo(x, 0);
    ctx.lineTo(x, 310);
    ctx.stroke();
  }

  // Draw parallax stars
  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  bgParticles.forEach(p => {
    ctx.fillRect(p.x, p.y, p.size, p.size);
  });

  // Draw Ground Line with neon glow
  ctx.save();
  ctx.shadowColor = '#00f3ff';
  ctx.shadowBlur = 15;
  ctx.strokeStyle = '#00f3ff';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(0, 310);
  ctx.lineTo(canvas.width, 310);
  ctx.stroke();
  ctx.restore();

  // Ground fill gradient
  const groundGrad = ctx.createLinearGradient(0, 310, 0, canvas.height);
  groundGrad.addColorStop(0, 'rgba(0, 243, 255, 0.15)');
  groundGrad.addColorStop(1, 'rgba(5, 5, 16, 0.9)');
  ctx.fillStyle = groundGrad;
  ctx.fillRect(0, 310, canvas.width, canvas.height - 310);

  // Draw Obstacles
  obstacles.forEach(obs => {
    ctx.save();
    ctx.shadowColor = obs.color;
    ctx.shadowBlur = 12;
    ctx.fillStyle = obs.color;

    if (obs.type === 'spike') {
      // Draw triangular spike
      ctx.beginPath();
      ctx.moveTo(obs.x, obs.y + obs.height);
      ctx.lineTo(obs.x + obs.width / 2, obs.y);
      ctx.lineTo(obs.x + obs.width, obs.y + obs.height);
      ctx.closePath();
      ctx.fill();
    } else {
      // Draw rectangular neon block
      ctx.fillRect(obs.x, obs.y, obs.width, obs.height);
      // Inner highlight
      ctx.strokeStyle = '#fff';
      ctx.lineWidth = 1;
      ctx.strokeRect(obs.x + 3, obs.y + 3, obs.width - 6, obs.height - 6);
    }
    ctx.restore();
  });

  // Draw Player Particles
  player.particles.forEach(p => {
    ctx.save();
    ctx.globalAlpha = p.alpha;
    ctx.fillStyle = p.color;
    ctx.shadowColor = p.color;
    ctx.shadowBlur = 8;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
    ctx.restore();
  });

  // Draw Player
  ctx.save();
  ctx.shadowColor = player.jumpsRemaining === 1 ? '#00f3ff' : (player.jumpsRemaining === 0 ? '#ff007f' : '#00f3ff');
  ctx.shadowBlur = 18;

  // Player body gradient
  const playerGrad = ctx.createLinearGradient(player.x, player.y, player.x, player.y + player.height);
  playerGrad.addColorStop(0, '#ffffff');
  playerGrad.addColorStop(0.3, player.jumpsRemaining === 0 ? '#ff007f' : '#00f3ff');
  playerGrad.addColorStop(1, '#002b55');

  ctx.fillStyle = playerGrad;
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Inner visor / detail on player
  ctx.fillStyle = '#ffffff';
  ctx.fillRect(player.x + player.width - 16, player.y + 10, 8, 14);

  ctx.restore();
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

// Initial draw
draw();
requestAnimationFrame(gameLoop);

